mapper.select:
select id, name, case when sex='01' then '男' when sex='02' then '女' end sex_Name, sex, age, case when teach_level='01' then '讲师' when teach_level='02' then '副教授' when teach_level='03' then '教授' else '其他' end teach_level_name, teach_level as teach_level, case when remark='01' then '数学教师' when remark='02' then '英语教师' when remark='03' then '语文教师' else '其他' end remark_name, remark, DATE_FORMAT(creation_time,'%Y-%m-%d %H:%i:%s') as creation_time, DATE_FORMAT(update_time,'%Y-%m-%d %H:%i:%s') as update_time, DATE_FORMAT(entry_time,'%Y-%m-%d %H:%i:%s') as entry_time from graduation_teach
and name like concat('%',#{name},'%')
and sex=#{sex}
and teach_level =#{teachLevel}
